import{_ as t,a0 as p,w as o,s as d,ao as r,I as e,x as a,a1 as i,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"在 Linux 上使用 Multitail | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上使用 Multitail | LCTT (201912) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上使用 Multitail | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上使用 Multitail | LCTT (201912) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201912/20191017 Using multitail on Linux","title":"在 Linux 上使用 Multitail","tag":"201912","desc":""},"relativePath":"201912/20191017 Using multitail on Linux.md","filePath":"[post].md"}'),c={name:"201912/20191017 Using multitail on Linux.md"};function u(h,s,g,m,k,b){const n=p("Link");return o(),d("div",null,[s[15]||(s[15]=r(`<h1 id="在-linux-上使用-multitail" tabindex="-1">在 Linux 上使用 Multitail <a class="header-anchor" href="#在-linux-上使用-multitail" aria-label="Permalink to “在 Linux 上使用 Multitail”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/201912/05/053423mpnrn95hqqknzheq.jpg" alt=""></p><p>當你想同時查看多個文件（尤其是日誌文件）的活動時，<code>multitail</code> 命令會非常有用。它的工作方式類似於多窗口形式的 <code>tail -f</code> 命令。也就是説，它顯示這些文件的底部和添加的新行。雖然通常使用簡單，但是 <code>multitail</code> 提供了一些命令列和交互式選項，在開始使用它之前，你應該瞭解它們。</p><h3 id="基本-multitail-使用" tabindex="-1">基本 multitail 使用 <a class="header-anchor" href="#基本-multitail-使用" aria-label="Permalink to “基本 multitail 使用”">​</a></h3><p><code>multitail</code> 的最簡單用法是在命令列中列出你要查看的文件名稱。此命令水平分割屏幕（即頂部和底部），並顯示每個文件的底部以及更新。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ multitail /var/log/syslog /var/log/dmesg</span></span></code></pre></div><p>顯示內容將像這樣拆分：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>+-----------------------+</span></span>
<span class="line"><span>|                       |</span></span>
<span class="line"><span>|                       |</span></span>
<span class="line"><span>+-----------------------|</span></span>
<span class="line"><span>|                       |</span></span>
<span class="line"><span>|                       |</span></span>
<span class="line"><span>+-----------------------+</span></span></code></pre></div><p>每個文件都有一行顯示該文件的文件編號（從 00 開始）、文件名、文件大小、最新內容的添加日期和時間。每個文件將被分配一半空間，而不論它的大小和活動情況。比如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>content lines from my1.log</span></span>
<span class="line"><span>more content</span></span>
<span class="line"><span>more lines</span></span>
<span class="line"><span></span></span>
<span class="line"><span>00] my1.log                                    59KB - 2019/10/14 12:12:09</span></span>
<span class="line"><span>content lines from my2.log</span></span>
<span class="line"><span>more content</span></span>
<span class="line"><span>more lines</span></span>
<span class="line"><span></span></span>
<span class="line"><span>01] my2.log                                   120KB - 2019/10/14 14:22:29</span></span></code></pre></div><p>請注意，如果你要求 <code>multitail</code> 顯示非文本文件或者你無權查看的文件，它不會報錯。你只是看不到內容。</p><p>你還可以使用通配符指定要查看的文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ multitail my*.log</span></span></code></pre></div><p>要記住的一件事是，<code>multitail</code> 將平均分割屏幕。如果指定的文件太多，那麼除非你採取額外的步驟查看之後的文件（參考下面的滾動選項），否則你將只會看到前面 7 個文件的前面幾行。確切的結果取決於終端窗口中有多少行可用。</p><p>按 <code>q</code> 退出 <code>multitail</code> 並返回到正常的屏幕視圖。</p><h3 id="分割屏幕" tabindex="-1">分割屏幕 <a class="header-anchor" href="#分割屏幕" aria-label="Permalink to “分割屏幕”">​</a></h3><p>如果你願意，<code>multitail</code> 也可以垂直分割你的終端窗口（即，左和右）。為此，請使用 <code>-s</code> 選項。如果指定了三個文件，那麼屏幕右側的窗口將會水平分隔。四個文件的話，你將擁有四個大小相等的窗口。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>+-----------+-----------+     +-----------+-----------+     +-----------+-----------+</span></span>
<span class="line"><span>|           |           |     |           |           |     |           |           |</span></span>
<span class="line"><span>|           |           |     |           |           |     |           |           |</span></span>
<span class="line"><span>|           |           |     |           +-----------+     +-----------+-----------+</span></span>
<span class="line"><span>|           |           |     |           |           |     |           |           |</span></span>
<span class="line"><span>|           |           |     |           |           |     |           |           |</span></span>
<span class="line"><span>+-----------+-----------+     +-----------+-----------+     +-----------+-----------+</span></span>
<span class="line"><span>         2 個文件                       3 個文件                       4 個文件</span></span></code></pre></div><p>如果要將屏幕分為三列，請使用 <code>multitail -s 3 file1 file2 file3</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>+-------+-------+-------+</span></span>
<span class="line"><span>|       |       |       |</span></span>
<span class="line"><span>|       |       |       |</span></span>
<span class="line"><span>|       |       |       |</span></span>
<span class="line"><span>|       |       |       |</span></span>
<span class="line"><span>|       |       |       |</span></span>
<span class="line"><span>+-------+-------+-------+</span></span>
<span class="line"><span>  3 個文件帶上 -s 3 選項</span></span></code></pre></div><h3 id="滾動" tabindex="-1">滾動 <a class="header-anchor" href="#滾動" aria-label="Permalink to “滾動”">​</a></h3><p>你可以上下滾動文件，但是需要按下 <code>b</code> 彈出選擇菜單，然後使用向上和向下箭頭按鈕選擇要滾動瀏覽的文件。然後按下回車鍵。然後，你可以再次使用向上和向下箭頭在放大的區域中滾動瀏覽各行。完成後按下 <code>q</code> 返回正常視圖。</p><h3 id="獲得幫助" tabindex="-1">獲得幫助 <a class="header-anchor" href="#獲得幫助" aria-label="Permalink to “獲得幫助”">​</a></h3><p>在 <code>multitail</code> 中按下 <code>h</code> 將打開一個幫助菜單，其中描述了一些基本操作，但是手冊頁提供了更多信息，如果莫想了解更多有關使用此工具的信息，請仔細閲讀。</p><p>默認情況下，你的系統上不會安裝 <code>multitail</code>，但是使用 <code>apt-get</code> 或 <code>yum</code> 可以使你輕鬆安裝。該工具提供了許多功能，不過它是基於字符顯示的，窗口邊框只是 <code>q</code> 和 <code>x</code> 的字符串組成的。當你需要關注文件更新時，它非常方便。</p><hr>`,26)),e("p",null,[s[1]||(s[1]=a("via: ",-1)),i(n,{href:"https://www.networkworld.com/article/3445228/using-multitail-on-linux.html"},{default:l(()=>[...s[0]||(s[0]=[a("https://www.networkworld.com/article/3445228/using-multitail-on-linux.html",-1)])]),_:1})]),e("p",null,[s[6]||(s[6]=a("作者：",-1)),i(n,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:l(()=>[...s[2]||(s[2]=[a("Sandra Henry-Stocker",-1)])]),_:1}),s[7]||(s[7]=a(" 選題：",-1)),i(n,{href:"https://github.com/lujun9972"},{default:l(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 譯者：",-1)),i(n,{href:"https://github.com/geekpi"},{default:l(()=>[...s[4]||(s[4]=[a("geekpi",-1)])]),_:1}),s[9]||(s[9]=a(" 校對：",-1)),i(n,{href:"https://github.com/wxy"},{default:l(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),e("p",null,[s[12]||(s[12]=a("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原創編譯，",-1)),i(n,{href:"https://linux.cn/"},{default:l(()=>[...s[11]||(s[11]=[a("Linux中國",-1)])]),_:1}),s[14]||(s[14]=a(" 榮譽推出",-1))])])}const C=t(c,[["render",u]]);export{y as __pageData,C as default};
